def get_max_sum(n):
    memo = {}

    def dp(x):
        if x in memo:
            return memo[x]
        if x == 0:
            return 0
        res = dp(x // 2) + dp(x // 3) + dp(x // 4) + dp(x // 5)
        memo[x] = max(res, x)
        return memo[x]

    return dp(n)
