def sequence(n):
    if n == 1 or n == 2:
        return 1

    s = [0, 1, 1]  # s[0] is unused, s[1] = 1, s[2] = 1

    for i in range(3, n + 1):
        s.append(s[s[i - 1] - 1] + s[i - s[i - 1] - 1])

    return s[n]
