def comb_sort(nums):
    if len(nums) <= 1:
        return nums

    shrink = 1.3
    gap = len(nums)
    sorted_flag = False

    while not sorted_flag:
        gap = int(gap // shrink)
        if gap <= 1:
            gap = 1
            sorted_flag = True

        i = 0
        while i + gap < len(nums):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                sorted_flag = False
            i += 1

    return nums
```

