def cal_sum(n):
    if n < 0:
        return 0

    # Base cases
    if n == 0:
        return 3
    if n == 1:
        return 0
    if n == 2:
        return 2

    # Initialize Perrin numbers
    a, b, c = 3, 0, 2
    total = a + b + c

    for _ in range(3, n + 1):
        a, b, c = b, c, a
        total += c

    return total
