def get_max_sum(n):
    memo = {}

    def dp(x):
        if x in memo:
            return memo[x]
        if x < 1:
            return 0
        res = max(dp(x//2) + dp(x//3) + dp(x//4) + dp(x//5), x)
        memo[x] = res
        return res

    return dp(n)
