import heapq

def large_product(nums1, nums2, N):
    # Generate all possible products using negative values to simulate max-heap
    products = []
    for num1 in nums1:
        for num2 in nums2:
            heapq.heappush(products, -(num1 * num2))

    # Extract N largest products
    result = []
    for _ in range(N):
        if products:
            result.append(-heapq.heappop(products))

    return result
```

