def get_max_sum(n):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def f(x):
        if x < 1:
            return 0
        return max(x, f(x//2) + f(x//3) + f(x//4) + f(x//5))

    return f(n)
```

