import heapq

def large_product(nums1, nums2, N):
    # Use a min-heap to keep track of the N largest products
    heap = []
    for a in nums1:
        for b in nums2:
            prod = a * b
            if len(heap) < N:
                heapq.heappush(heap, prod)
            else:
                heapq.heappushpop(heap, prod)
    # The heap now contains the N largest products, return them sorted
    return sorted(heap, reverse=True)
